if ( ! function_exists( 'rbh_seo06_20261016_enrich_organization' ) ) {
    function rbh_seo06_20261016_enrich_organization( $data ) {
        if ( ! is_array( $data ) || strtolower( (string) wp_parse_url( home_url( '/' ), PHP_URL_HOST ) ) !== 'rentbikehanoi.com' ) {
            return $data;
        }
        $types = isset( $data['@type'] ) ? (array) $data['@type'] : array();
        $data['@type'] = array_values( array_unique( array_merge( $types, array( 'Organization', 'Place', 'LocalBusiness' ) ) ) );
        $aliases = isset( $data['alternateName'] ) ? (array) $data['alternateName'] : array();
        $data['alternateName'] = array_values( array_unique( array_merge( $aliases, array( 'Thuê xe máy Nguyễn Hà', 'Motorbike Nguyen Ha' ) ) ) );
        $data['telephone'] = '+84334699969';
        $address = isset( $data['address'] ) && is_array( $data['address'] ) ? $data['address'] : array();
        $data['address'] = array_merge( $address, array(
            '@type' => 'PostalAddress',
            'streetAddress' => 'Ngõ 5 Nguyễn Văn Cừ, Bồ Đề',
            'addressLocality' => 'Long Biên',
            'addressRegion' => 'Hà Nội',
            'addressCountry' => 'VN'
        ) );
        $data['openingHoursSpecification'] = array( array(
            '@type' => 'OpeningHoursSpecification',
            'dayOfWeek' => array( 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday' ),
            'opens' => '09:00',
            'closes' => '21:00'
        ) );
        return $data;
    }
}
add_filter( 'wpseo_schema_organization', 'rbh_seo06_20261016_enrich_organization', 20, 1 );

if ( ! function_exists( 'rbh_seo06_20261016_visible_faq' ) ) {
    function rbh_seo06_20261016_visible_faq( $data ) {
        if ( ! is_array( $data ) || ! is_page( 182 ) || isset( $data['mainEntity'] ) || strtolower( (string) wp_parse_url( home_url( '/' ), PHP_URL_HOST ) ) !== 'rentbikehanoi.com' ) {
            return $data;
        }
        $page = get_post( 182 );
        if ( ! $page || $page->post_status !== 'publish' ) {
            return $data;
        }
        $wanted = array( 'What are your operating hours?', 'How much does motorbike rental cost in Hanoi?' );
        $questions = array();
        $matches = array();
        preg_match_all( '~<details\b[^>]*>\s*<summary\b[^>]*>(.*?)</summary>(.*?)</details>~is', $page->post_content, $matches, PREG_SET_ORDER );
        foreach ( $matches as $match ) {
            $question = trim( preg_replace( '/\s+/u', ' ', html_entity_decode( wp_strip_all_tags( $match[1] ), ENT_QUOTES | ENT_HTML5, 'UTF-8' ) ) );
            if ( ! in_array( $question, $wanted, true ) ) {
                continue;
            }
            $answer_markup = preg_replace( '~</?(?:p|div|br|table|thead|tbody|tr|th|td|ul|ol|li|h[1-6])\b[^>]*>~i', ' ', $match[2] );
            $answer = trim( preg_replace( '/\s+/u', ' ', html_entity_decode( wp_strip_all_tags( $answer_markup ), ENT_QUOTES | ENT_HTML5, 'UTF-8' ) ) );
            if ( $answer !== '' ) {
                $questions[] = array( '@type' => 'Question', 'name' => $question, 'acceptedAnswer' => array( '@type' => 'Answer', 'text' => $answer ) );
            }
        }
        if ( count( $questions ) !== count( $wanted ) ) {
            return $data;
        }
        $types = isset( $data['@type'] ) ? (array) $data['@type'] : array();
        $data['@type'] = array_values( array_unique( array_merge( $types, array( 'WebPage', 'FAQPage' ) ) ) );
        $data['mainEntity'] = $questions;
        return $data;
    }
}
add_filter( 'wpseo_schema_webpage', 'rbh_seo06_20261016_visible_faq', 20, 1 );
